const DATA_KEY='murmure-data-v1';let lang='fr',data,activeId='eloise',view='chat',selectedColor='#d7c6ba',modalTutorialStep=0,timerToast;
function t(key){return (words[lang]||words.fr)[key]||key}function character(id=activeId){return data.characters.find(c=>c.id===id)||data.characters[0]}function localized(x){return typeof x==='object'?(x?.[lang]||x?.fr||''):x}
function blankData(){return{characters:seed.map(c=>({...c,messages:[]})),active:'eloise',profile:'Alex Morgan'}}
function loadData(){try{const d=JSON.parse(localStorage.getItem(DATA_KEY));if(d&&Array.isArray(d.characters)&&d.characters.length){data=d; if(!data.characters.some(c=>c.id===data.active))data.active=data.characters[0].id;return}}catch{}data=blankData();persist()}
function persist(){try{localStorage.setItem(DATA_KEY,JSON.stringify(data))}catch(e){toast(lang==='fr'?'Stockage navigateur indisponible.':'Browser storage unavailable.')}}
function photoStyle(c){return c.photo?`url("${c.photo}")`:`linear-gradient(145deg,${c.color||'#c5cabb'},#918b80)`}
function setAvatar(el,c){el.style.backgroundImage=photoStyle(c);if(!c.photo)el.style.backgroundColor=c.color||'#c5cabb'}
function applyLanguage(){document.documentElement.lang=lang;$$('[data-i18n]').forEach(el=>{const val=t(el.dataset.i18n);if(val)el.textContent=val});$$('[data-placeholder]').forEach(el=>el.placeholder=t(el.dataset.placeholder));$('#language-label').textContent=lang.toUpperCase();$('#crumb-active').textContent=view==='chat'?t('chatTitle'):t('libraryTitle');render()}
function renderSidebar(){const host=$('#character-list');host.innerHTML=data.characters.map(c=>`<button class="character-item ${c.id===activeId?'selected':''}" data-id="${c.id}"><span class="mini-avatar" style="background-image:${photoStyle(c)}"></span><span class="character-item-copy"><strong>${esc(c.name)}</strong><small>${esc(localized(c.role))}</small></span>${c.messages?.length?'<span class="character-unread"></span>':''}</button>`).join('');host.querySelectorAll('.character-item').forEach(b=>b.onclick=()=>selectCharacter(b.dataset.id));$('#chat-count').textContent=data.characters.length}
function renderDetails(){const c=character();if(!c)return;setAvatar($('#chat-avatar'),c);setAvatar($('#typing-avatar'),c);$('#chat-name').textContent=c.name;$('#chat-tagline').textContent=localized(c.role);$('#typing-label').textContent=`${c.name} ${t('loading')}`;$('#detail-cover').style.backgroundImage=photoStyle(c);$('#detail-name').textContent=c.name;$('#detail-role').textContent=localized(c.role);$('#detail-bio').textContent=localized(c.bio);$('#trait-list').innerHTML=(c.traits?.[lang]||c.traits?.fr||[]).map(x=>`<span class="trait-tag">${esc(x)}</span>`).join('');$('#style-note').textContent=localized(c.style);$('#prompt-row').innerHTML=(c.prompts?.[lang]||c.prompts?.fr||[]).map(x=>`<button type="button" class="prompt-chip">${esc(x)}</button>`).join('');$('#prompt-row').querySelectorAll('button').forEach(b=>b.onclick=()=>{ $('#message-input').value=b.textContent;sendMessage()});renderMessages()}
function renderMessages(){const c=character(),host=$('#messages');const msgs=c.messages||[];if(!msgs.length){host.innerHTML=messageHTML({role:'assistant',text:localized(c.opening),time:new Date().toLocaleTimeString(lang==='fr'?'fr-FR':'en-US',{hour:'2-digit',minute:'2-digit'})},c);return}host.innerHTML=msgs.map(m=>messageHTML(m,c)).join('');}
function messageHTML(m,c){const mine=m.role==='user';return `<div class="message-row ${mine?'mine':''}">${!mine?`<span class="message-avatar" style="background-image:${photoStyle(c)}"></span>`:''}<div class="bubble-wrap">${!mine?`<div class="bubble-meta">${esc(c.name)} · ${esc(m.time||'')}</div>`:''}<div class="bubble">${esc(m.text)}</div><div class="message-time">${mine?esc(t('you')+' · '+(m.time||'')):''}</div></div>${mine?'':' '}</div>`}
function render(){if(!data)return;activeId=data.active||activeId;renderSidebar();renderDetails();$('#profile-name').textContent=data.profile||'Alex Morgan';$$('.side-link').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#crumb-active').textContent=view==='chat'?t('chatTitle'):t('libraryTitle');renderLibrary($('#character-search')?.value||'')}
function selectCharacter(id){activeId=id;data.active=id;persist();render();if(view!=='chat')setView('chat')}
function setView(v){view=v;$('#chat-view').classList.toggle('active',v==='chat');$('#characters-view').classList.toggle('active',v==='characters');$$('.side-link').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#crumb-active').textContent=v==='chat'?t('chatTitle'):t('libraryTitle');if(v==='characters')renderLibrary($('#character-search').value)}
function renderLibrary(filter=''){const grid=$('#library-grid'),empty=$('#empty-library');if(!grid)return;const q=filter.trim().toLowerCase();const found=data.characters.filter(c=>(`${c.name} ${localized(c.role)} ${localized(c.bio)}`).toLowerCase().includes(q));grid.innerHTML=found.map(c=>`<article class="library-card" data-id="${c.id}"><div class="library-image" style="background-image:${photoStyle(c)}"><span class="library-private"><i class="privacy-dot"></i>${t('private')}</span></div><div class="library-card-copy"><div class="library-card-title"><h3>${esc(c.name)}</h3><span>↗</span></div><p>${esc(localized(c.role))} · ${esc(localized(c.bio))}</p><div class="library-traits">${(c.traits?.[lang]||c.traits?.fr||[]).slice(0,3).map(x=>`<span>${esc(x)}</span>`).join('')}</div></div></article>`).join('');grid.classList.toggle('hidden',!found.length);empty.classList.toggle('hidden',!!found.length);if(!found.length&&q)empty.querySelector('h2').textContent=t('noMatch');else empty.querySelector('h2').textContent=t('emptyLibrary');grid.querySelectorAll('.library-card').forEach(card=>card.onclick=()=>selectCharacter(card.dataset.id))}
