function deleteCharacter(id){if(data.characters.length===1){toast(lang==='fr'?'Gardez au moins un personnage dans votre espace.':'Keep at least one character in your space.');return}if(!confirm(t('deleteConfirm')))return;data.characters=data.characters.filter(c=>c.id!==id);if(data.active===id)data.active=data.characters[0].id;activeId=data.active;persist();closeModal();render();toast(t('deleted'))}
function showTutorial(step=0){modalTutorialStep=step;const list=slides[lang];const [icon,title,copy]=list[step];showModal(`<div class="modal-kicker">${t('tutorialTitle')}</div><div class="tutorial-progress"><span style="width:${(step+1)/list.length*100}%"></span></div><div class="tutorial-slide-number">${String(step+1).padStart(2,'0')} / ${String(list.length).padStart(2,'0')}</div><div class="tutorial-illustration">${icon}</div><div class="tutorial-content"><h3>${title}</h3><p>${copy}</p><div class="tutorial-dots">${list.map((_,i)=>`<span class="${i===step?'active':''}"></span>`).join('')}</div></div><div class="modal-actions"><button class="text-button" id="tutorial-skip">${t('skip')}</button>${step?`<button class="secondary-button" id="tutorial-back">${t('back')}</button>`:''}<button class="modal-primary" id="tutorial-next">${step===list.length-1?t('done'):t('next')}</button></div>`);$('#tutorial-skip').onclick=closeModal;$('#tutorial-back')?.addEventListener('click',()=>showTutorial(step-1));$('#tutorial-next').onclick=()=>step===list.length-1?closeModal():showTutorial(step+1)}
function showSafety(){showModal(`<div class="modal-kicker">${t('guidelines')}</div><h2 id="modal-title">${lang==='fr'?'Un espace créatif, avec des limites claires.':'A creative space, with clear boundaries.'}</h2><p class="modal-subtitle">${lang==='fr'?'Vous pouvez explorer des idées, des styles et des histoires tout en gardant un cadre sûr et respectueux.':'Explore ideas, styles, and stories while keeping things safe and respectful.'}</p><div class="safety-list"><div class="safety-row"><span>✓</span><span><strong>${lang==='fr'?'Autorisé :':'Allowed:'}</strong> ${lang==='fr'?'mode, maillots de bain, robes, looks sexy non explicites, romance et affection.':'fashion, swimsuits, dresses, non-explicit sexy styles, romance, and affection.'}</span></div><div class="safety-row"><span>×</span><span><strong>${lang==='fr'?'Non autorisé :':'Not allowed:'}</strong> ${lang==='fr'?'nudité, contenu sexuel explicite, ou création d’images/vidéos à caractère sexuel.':'nudity, explicit sexual content, or sexual image/video creation.'}</span></div><div class="safety-row"><span>⌑</span><span><strong>${lang==='fr'?'Vie privée :':'Privacy:'}</strong> ${lang==='fr'?'vos personnages ne sont pas publiés. Les données restent dans ce navigateur.':'your characters are not published. Data stays in this browser.'}</span></div></div><div class="modal-actions"><button class="modal-primary" id="safety-ok">${lang==='fr'?'J’ai compris':'Got it'}</button></div>`);$('#safety-ok').onclick=closeModal}
const VAULT_PREFIX='murmure-vault-v1:';
async function deriveKey(password,salt){const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:180000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
function bytesTo64(bytes){return btoa(String.fromCharCode(...new Uint8Array(bytes)))}function from64(text){return Uint8Array.from(atob(text),c=>c.charCodeAt(0))}
function showVault(){const email=localStorage.getItem('murmure-vault-email')||'';const saved=email?localStorage.getItem(VAULT_PREFIX+email.toLowerCase()):null;showModal(`<div class="modal-kicker">${t('myProfile')}</div><div class="vault-lock">⌑</div><h2 id="modal-title">${lang==='fr'?'Votre espace vous suit.':'Your space, wherever you go.'}</h2><p class="modal-subtitle">${lang==='fr'?'Chiffrez une sauvegarde privée avec votre adresse et un mot de passe. Elle reste stockée uniquement dans ce navigateur.':'Encrypt a private backup with your email and a password. It stays stored only in this browser.'}</p><form id="vault-form"><div class="field"><label>${lang==='fr'?'Adresse e-mail':'Email address'}</label><input name="email" type="email" required value="${esc(email)}" placeholder="vous@exemple.com"></div><div class="field"><label>${lang==='fr'?'Mot de passe':'Password'}</label><input name="password" type="password" required minlength="8" autocomplete="new-password" placeholder="${lang==='fr'?'8 caractères minimum':'At least 8 characters'}"></div><div class="vault-note">⌑ <span>${esc(t('accountNote'))}</span></div><div class="modal-actions"><button type="button" class="secondary-button" id="vault-cancel">${t('cancel')}</button><button type="submit" class="modal-primary">${saved?(lang==='fr'?'Déverrouiller / actualiser':'Unlock / update'):(lang==='fr'?'Chiffrer et sauvegarder':'Encrypt & save')}</button></div></form>${saved?`<div class="modal-secondary-row">${lang==='fr'?'Une sauvegarde chiffrée existe pour cette adresse.':'An encrypted backup exists for this address.'}</div>`:''}`);$('#vault-cancel').onclick=closeModal;$('#vault-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),mail=String(f.get('email')).trim().toLowerCase(),password=String(f.get('password'));if(password.length<8){toast(lang==='fr'?'Choisissez un mot de passe de 8 caractères minimum.':'Choose a password with at least 8 characters.');return}try{const prior=localStorage.getItem(VAULT_PREFIX+mail);if(prior){const parsed=JSON.parse(prior);try{const key=await deriveKey(password,from64(parsed.salt));const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:from64(parsed.iv)},key,from64(parsed.data));const restored=JSON.parse(new TextDecoder().decode(plain));if(!restored.characters?.length)throw Error('empty');data=restored;activeId=data.active||data.characters[0].id;toast(t('vaultOpened'))}catch{toast(t('wrongPass'));return}}const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await deriveKey(password,salt),cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(JSON.stringify(data)));localStorage.setItem(VAULT_PREFIX+mail,JSON.stringify({salt:bytesTo64(salt),iv:bytesTo64(iv),data:bytesTo64(cipher)}));localStorage.setItem('murmure-vault-email',mail);data.profile=mail.split('@')[0];persist();closeModal();render();toast(t('vaultSaved'))}catch(err){console.error(err);toast(lang==='fr'?'Impossible de chiffrer la sauvegarde dans ce navigateur.':'Could not encrypt a backup in this browser.')}}}
function attachVaultExport(){const email=localStorage.getItem('murmure-vault-email');const blob=email&&localStorage.getItem(VAULT_PREFIX+email);if(!blob){showVault();return}const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([blob],{type:'application/json'}));link.download='murmure-sauvegarde-chiffree.json';link.click();URL.revokeObjectURL(link.href);toast(lang==='fr'?'Sauvegarde chiffrée téléchargée.':'Encrypted backup downloaded.')}
function bind(){
$('#chat-form').addEventListener('submit',e=>{e.preventDefault();sendMessage()});$('#message-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage()}});$('#message-input').addEventListener('input',e=>{e.target.style.height='auto';e.target.style.height=Math.min(e.target.scrollHeight,100)+'px'});
$('#language-toggle').onclick=()=>{lang=lang==='fr'?'en':'fr';applyLanguage()};$$('.side-link').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#create-character').onclick=()=>showCharacterForm();$('#quick-create').onclick=()=>showCharacterForm();$('#library-create').onclick=()=>showCharacterForm();$('#empty-create').onclick=()=>showCharacterForm();$('#edit-character').onclick=()=>showCharacterForm(activeId);$('#character-menu').onclick=()=>showCharacterForm(activeId);$('#open-tutorial').onclick=()=>showTutorial();$('#safety-link').onclick=showSafety;$('#clear-chat').onclick=()=>{if(!confirm(t('eraseConfirm')))return;character().messages=[];persist();renderMessages();toast(t('chatCleared'))};$('#character-search').addEventListener('input',e=>renderLibrary(e.target.value));$('#open-vault').onclick=showVault;$('#attach-button').onclick=attachVaultExport;
$('#menu-button').onclick=()=>{$('#sidebar').classList.add('open');$('#scrim').classList.add('show')};$('#close-sidebar').onclick=closeSidebar;$('#scrim').onclick=closeSidebar;function closeSidebar(){$('#sidebar').classList.remove('open');$('#scrim').classList.remove('show')}
$('#modal-close').onclick=closeModal;$('#modal-backdrop').addEventListener('click',e=>{if(e.target===$('#modal-backdrop'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});document.querySelector('.profile-button').addEventListener('contextmenu',e=>{e.preventDefault();showVault()});
}
loadData();bind();render();const tutorialSeen=localStorage.getItem('murmure-tutorial-seen');if(!tutorialSeen){setTimeout(()=>{showTutorial();localStorage.setItem('murmure-tutorial-seen','1')},450)}

